INSERT INTO public.rooms (name, capacity, location, description, amenities, is_active) VALUES
('ห้องศึกษาเดี่ยว A101 (Silent Focus)', 2, 'อาคารหอสมุดกลาง ชั้น 1', 'ห้องอ่านหนังสือส่วนบุคคล บรรยากาศเงียบสงบ เหมาะสำหรับอ่านหนังสือสอบหรือทำงานวิจัยเดี่ยว', ARRAY['Wi-Fi ความเร็วสูง', 'ปลั๊กไฟ 4 ช่อง', 'โคมไฟอ่านหนังสือแบบถนอมสายตา', 'เครื่องปรับอากาศ'], TRUE),
('ห้องศึกษากลุ่ม B201 (Brainstorm Hub)', 6, 'อาคารหอสมุดกลาง ชั้น 2', 'ห้องศึกษาและทำงานกลุ่มขนาดกลาง พร้อมหน้าจอ Smart TV และกระดาน Whiteboard สำหรับระดมสมอง', ARRAY['Wi-Fi ความเร็วสูง', 'Smart TV 55 นิ้ว', 'กระดาน Whiteboard พร้อมปากกา', 'ปลั๊กไฟทุกที่นั่ง'], TRUE),
('ห้องศึกษากลุ่ม B202 (Collaboration Room)', 8, 'อาคารหอสมุดกลาง ชั้น 2', 'ห้องทำงานกลุ่มขนาดใหญ่ รองรับการประชุม สัมมนา และติวหนังสือกลุ่ม', ARRAY['Wi-Fi ความเร็วสูง', 'โปรเจกเตอร์ & จอรับภาพ', 'Whiteboard ขนาดใหญ่', 'เครื่องปรับอากาศแยกส่วน', 'ปลั๊กไฟรอบห้อง'], TRUE),
('ห้องศึกษาเดี่ยว A102 (Quiet Pod)', 2, 'อาคารหอสมุดกลาง ชั้น 1', 'ห้องศึกษาเดี่ยวพร้อมเก้าอี้ Ergonomic ช่วยลดอาการเมื่อยล้าจากการนั่งอ่านหนังสือเป็นเวลานาน', ARRAY['Wi-Fi ความเร็วสูง', 'เก้าอี้ Ergonomic', 'ปลั๊กไฟและพอร์ต USB', 'โคมไฟปรับระดับแสงได้'], TRUE),
('ห้องมัลติมีเดีย C301 (Media & Presentation)', 10, 'อาคารหอสมุดกลาง ชั้น 3', 'ห้องพร้อมอุปกรณ์มัลติมีเดียครบครันสำหรับการซ้อมนำเสนองาน การอัดวิดีโอคลิป หรือการประชุมออนไลน์', ARRAY['Wi-Fi ความเร็วสูง', 'Smart TV 65 นิ้ว 4K', 'ไมโครโฟนไร้สาย', 'Soundbar', 'เว็บแคม Conference'], TRUE);
